#!/usr/bin/env python3
"""Analyze JSON data: compute statistics, group by categories, generate summary report."""

import json
import math
import sys
from collections import Counter, defaultdict


def load_json(path):
    with open(path) as f:
        data = json.load(f)
    if isinstance(data, list):
        return data
    return [data]


def try_numeric(val):
    """Return float if value is numeric, else None."""
    if val is None:
        return None
    if isinstance(val, (int, float)):
        return float(val)
    if isinstance(val, str):
        val = val.strip()
        if val in ("", "N/A", "NA", "n/a", "--", "-", "null", "none", "None"):
            return None
        try:
            return float(val)
        except ValueError:
            return None
    return None


def try_bool(val):
    """Return True/False if value is boolean-like, else None."""
    if val is None:
        return None
    if isinstance(val, bool):
        return val
    if isinstance(val, str):
        low = val.strip().lower()
        if low in ("true", "yes", "1", "y"):
            return True
        if low in ("false", "no", "0", "n"):
            return False
    return None


def mean(values):
    return sum(values) / len(values)


def median(values):
    s = sorted(values)
    n = len(s)
    mid = n // 2
    if n % 2 == 0:
        return (s[mid - 1] + s[mid]) / 2
    return s[mid]


def std_dev(values):
    m = mean(values)
    variance = sum((x - m) ** 2 for x in values) / len(values)
    return math.sqrt(variance)


def compute_numeric_stats(values):
    """Compute stats for a list of numeric values."""
    if not values:
        return None
    return {
        "count": len(values),
        "mean": round(mean(values), 4),
        "median": round(median(values), 4),
        "std_dev": round(std_dev(values), 4),
        "min": min(values),
        "max": max(values),
        "sum": round(sum(values), 4),
    }


def classify_fields(records):
    """Identify numeric, boolean, categorical, and text fields."""
    if not records:
        return {}, {}, {}, {}

    all_keys = set()
    for r in records:
        all_keys.update(r.keys())

    numeric_fields = {}
    bool_fields = {}
    categorical_fields = {}
    text_fields = {}

    for key in all_keys:
        nums = []
        bools = []
        cats = []
        for r in records:
            val = r.get(key)
            n = try_numeric(val)
            b = try_bool(val)
            if n is not None:
                nums.append(n)
            elif b is not None:
                bools.append(b)
            elif val is not None and str(val).strip() != "":
                cats.append(str(val).strip())

        # Field is numeric if >50% of non-empty values are numeric
        total = len(nums) + len(bools) + len(cats)
        if total == 0:
            continue
        if len(nums) / total > 0.5 and nums:
            numeric_fields[key] = nums
        elif len(bools) / total > 0.5 and bools:
            bool_fields[key] = bools
        elif len(cats) / total > 0.5:
            # Categorical if <20 unique values, else text
            unique = set(cats)
            if len(unique) <= 20:
                categorical_fields[key] = cats
            else:
                text_fields[key] = cats

    return numeric_fields, bool_fields, categorical_fields, text_fields


def group_by(records, key):
    """Group records by a field value."""
    groups = defaultdict(list)
    missing = []
    for r in records:
        val = r.get(key)
        if val is None or str(val).strip() == "":
            missing.append(r)
        else:
            groups[str(val).strip()].append(r)
    result = dict(groups)
    if missing:
        result["(missing)"] = missing
    return result


def generate_report(records, path):
    """Generate a full analysis report."""
    lines = []
    lines.append("=" * 60)
    lines.append("JSON DATA ANALYSIS REPORT")
    lines.append("=" * 60)
    lines.append(f"Source file : {path}")
    lines.append(f"Total records: {len(records)}")
    lines.append("")

    numeric_fields, bool_fields, cat_fields, text_fields = classify_fields(records)

    # --- Numeric statistics ---
    if numeric_fields:
        lines.append("-" * 60)
        lines.append("NUMERIC FIELD STATISTICS")
        lines.append("-" * 60)
        for field, values in sorted(numeric_fields.items()):
            stats = compute_numeric_stats(values)
            lines.append(f"\n  {field}  (valid: {stats['count']}/{len(records)})")
            lines.append(f"    Mean   : {stats['mean']}")
            lines.append(f"    Median : {stats['median']}")
            lines.append(f"    Std Dev: {stats['std_dev']}")
            lines.append(f"    Min    : {stats['min']}")
            lines.append(f"    Max    : {stats['max']}")
            lines.append(f"    Sum    : {stats['sum']}")
        lines.append("")

    # --- Boolean field distribution ---
    if bool_fields:
        lines.append("-" * 60)
        lines.append("BOOLEAN FIELD DISTRIBUTION")
        lines.append("-" * 60)
        for field, values in sorted(bool_fields.items()):
            counts = Counter(values)
            lines.append(f"\n  {field}  (valid: {len(values)}/{len(records)})")
            lines.append(f"    True : {counts.get(True, 0)} ({counts.get(True, 0)/len(values)*100:.1f}%)")
            lines.append(f"    False: {counts.get(False, 0)} ({counts.get(False, 0)/len(values)*100:.1f}%)")
        lines.append("")

    # --- Categorical field distribution ---
    if cat_fields:
        lines.append("-" * 60)
        lines.append("CATEGORICAL FIELD DISTRIBUTION")
        lines.append("-" * 60)
        for field, values in sorted(cat_fields.items()):
            counts = Counter(values)
            lines.append(f"\n  {field}  (valid: {len(values)}/{len(records)}, unique: {len(counts)})")
            for val, cnt in counts.most_common(10):
                lines.append(f"    {val!r:30s} : {cnt}")
        lines.append("")

    # --- Text fields (just note them) ---
    if text_fields:
        lines.append("-" * 60)
        lines.append("TEXT FIELDS (high cardinality, skipped)")
        lines.append("-" * 60)
        for field in sorted(text_fields):
            lines.append(f"  {field}")
        lines.append("")

    # --- Group-by analysis on categorical fields ---
    groupable = {}
    for field in cat_fields:
        unique = set(cat_fields[field])
        if 1 < len(unique) <= 10:
            groupable[field] = unique

    if groupable and numeric_fields:
        lines.append("-" * 60)
        lines.append("GROUP-BY ANALYSIS")
        lines.append("-" * 60)
        for cat_field in sorted(groupable):
            for num_field in sorted(numeric_fields):
                groups = group_by(records, cat_field)
                lines.append(f"\n  Group by '{cat_field}', aggregate '{num_field}':")
                lines.append(f"  {'Group':<20s} {'Count':>6s} {'Mean':>10s} {'Median':>10s} {'StdDev':>10s}")
                lines.append(f"  {'-'*20} {'-'*6} {'-'*10} {'-'*10} {'-'*10}")
                for grp, recs in sorted(groups.items()):
                    vals = [try_numeric(r.get(num_field)) for r in recs]
                    vals = [v for v in vals if v is not None]
                    if vals:
                        lines.append(
                            f"  {grp:<20s} {len(vals):>6d} "
                            f"{mean(vals):>10.2f} {median(vals):>10.2f} {std_dev(vals):>10.2f}"
                        )
                    else:
                        lines.append(f"  {grp:<20s} {'0':>6s} {'N/A':>10s} {'N/A':>10s} {'N/A':>10s}")
        lines.append("")

    # --- Data quality summary ---
    lines.append("-" * 60)
    lines.append("DATA QUALITY SUMMARY")
    lines.append("-" * 60)
    all_keys = set()
    for r in records:
        all_keys.update(r.keys())
    for key in sorted(all_keys):
        empty = sum(1 for r in records if r.get(key) in (None, "", "N/A", "NA", "n/a", "--", "-", "null", "none", "None"))
        if empty > 0:
            lines.append(f"  {key:<20s} : {empty}/{len(records)} missing or invalid ({empty/len(records)*100:.1f}%)")
    lines.append("")
    lines.append("=" * 60)
    lines.append("END OF REPORT")
    lines.append("=" * 60)
    return "\n".join(lines)


def main():
    if len(sys.argv) < 2:
        print("Usage: python json_analyzer.py <data.json> [output_report.txt]")
        sys.exit(1)

    path = sys.argv[1]
    records = load_json(path)
    report = generate_report(records, path)

    print(report)

    if len(sys.argv) >= 3:
        out_path = sys.argv[2]
        with open(out_path, "w") as f:
            f.write(report)
        print(f"\nReport saved to: {out_path}")


if __name__ == "__main__":
    main()
